"""Test split specification (labelled per data/guideline.md before any system was run on it).

Four documentation families that the dev split does not use: SQLite limits, Redis replication,
Kubernetes probes and PostgreSQL transaction isolation. Per family: one all-supported answer (with
reasoning-type supported claims), one subtle-distortion answer, one extrinsic-hallucination answer,
one multi-passage answer and one natural answer generated by glm-5.3 (data/gen_natural.py). Plus three
edge cases. Passages are "<source>:<paragraph>" references into data/sources/*.json; evidence "p" indexes
the case's own passage list. data/build.py validates every quote and anchor.
"""
S, C, U = "SUPPORTED", "CONTRADICTED", "UNSUPPORTED"


def cl(text, anchor, verdict, typ, ev=(), mode="any", note=None, contestable=False):
    d = {"text": text, "anchor": anchor, "verdict": verdict, "type": typ, "evidence": [{"p": p, "quote": q} for p, q in ev]}
    if mode != "any":
        d["evidence_mode"] = mode
    if note:
        d["note"] = note
    if contestable:
        d["contestable"] = True
    return d


